import { LOGGED, type LiWEApp, type LiWECtx, type LiWEResponse, permissions_register, routeBody, routeGet } from '@backend/liwe3';
import {
	tag_add,
	tag_bulk_add,
	tag_bulk_remove,
	tag_find_by_affinity,
	tag_find_by_tags,
	tag_list,
	tag_list_by_module,
	tag_list_by_object,
	tag_merge,
	tag_object,
	tag_remove_object,
	tag_search,
	tag_stats,
	tag_update_relevance,
} from './methods';
import { listeners_init } from './listeners';
import { TAGS_PERMISSIONS, TAGS_PERM_ADMIN, TAGS_PERM_UPDATE } from './perms';

// NOTE: the tags module is hand-written and was never generated by flow2code.
// Route gates mirror work/modules/tags.json and are applied by hand (a drift
// test compares them). The methods keep their legacy (app, params) signature,
// adapted to the (ctx, params) shape of routeGet / routeBody by _legacy().

/**
 * Adapts a legacy (app, params) tags method to the (ctx, params) method shape.
 *
 * @param fn - the legacy method
 * @returns a method usable by routeGet / routeBody
 */
const _legacy = <P>( fn : ( app : LiWEApp, params : P ) => Promise<LiWEResponse> ) => ( ctx : LiWECtx, params : P ) => fn( ctx.app, params );

const tag_list_route = _legacy( tag_list );
const tag_add_route = _legacy( tag_add );
const tag_object_route = _legacy( tag_object );
const tag_remove_object_route = _legacy( tag_remove_object );
const tag_list_by_object_route = _legacy( tag_list_by_object );
const tag_find_by_tags_route = _legacy( tag_find_by_tags );
const tag_find_by_affinity_route = _legacy( tag_find_by_affinity );
const tag_search_route = _legacy( tag_search );
const tag_update_relevance_route = _legacy( tag_update_relevance );
const tag_stats_route = _legacy( tag_stats );
const tag_bulk_add_route = _legacy( tag_bulk_add );
const tag_bulk_remove_route = _legacy( tag_bulk_remove );
const tag_list_by_module_route = _legacy( tag_list_by_module );
const tag_merge_route = _legacy( tag_merge );

// Module initialization function
export const module_init = async ( app : LiWEApp ) => {
	console.log( '=== Module: tags' );

	listeners_init( app );

	app.hono.get( '/api/tags/list', routeGet( tag_list_route, { perms: LOGGED } ) );

	// Phase 1 (Kanban): every logged user can create tags and tag / untag objects (work/modules/tags.json)
	app.hono.post( '/api/tags/tag/add', routeBody( tag_add_route, { perms: LOGGED } ) );

	app.hono.post( '/api/tags/obj/add', routeBody( tag_object_route, { perms: LOGGED } ) );

	app.hono.delete( '/api/tags/obj/del', routeBody( tag_remove_object_route, { perms: LOGGED } ) );

	app.hono.get( '/api/tags/obj/list', routeGet( tag_list_by_object_route, { perms: LOGGED } ) );

	app.hono.post( '/api/tags/find/by/tags', routeBody( tag_find_by_tags_route, { perms: LOGGED } ) );

	app.hono.post( '/api/tags/find/by/affinity', routeBody( tag_find_by_affinity_route, { perms: LOGGED } ) );

	app.hono.post( '/api/tags/search', routeBody( tag_search_route, { perms: LOGGED } ) );

	app.hono.patch( '/api/tags/relevance/update', routeBody( tag_update_relevance_route, { perms: [ TAGS_PERM_UPDATE, TAGS_PERM_ADMIN ] } ) );

	app.hono.post( '/api/tags/stats', routeBody( tag_stats_route, { perms: LOGGED } ) );

	app.hono.post( '/api/tags/bulk/add', routeBody( tag_bulk_add_route, { perms: [ TAGS_PERM_ADMIN ] } ) );

	app.hono.delete( '/api/tags/bulk/del', routeBody( tag_bulk_remove_route, { perms: [ TAGS_PERM_ADMIN ] } ) );

	app.hono.post( '/api/tags/list/by/module', routeBody( tag_list_by_module_route, { perms: LOGGED } ) );

	app.hono.patch( '/api/tags/merge', routeBody( tag_merge_route, { perms: [ TAGS_PERM_ADMIN ] } ) );

	// Register tags module permissions
	permissions_register( {
		module: 'tags',
		perms: TAGS_PERMISSIONS,
	} );
};
